          properties = {
            ["atMostOnce"] = true,
            ["script"] = "local Transform = require \"util/Transform\"\nlocal Rect = unpack(require \"util/Shapes\")\nlocal Layout = require \"util/Layout\"\n\nlocal Action = require \"actions/Action\"\nlocal Animate = require \"actions/Animate\"\nlocal TypeText = require \"actions/TypeText\"\nlocal MessageBox = require \"actions/MessageBox\"\nlocal PlayAudio = require \"actions/PlayAudio\"\nlocal Ease = require \"actions/Ease\"\nlocal Move = require \"actions/Move\"\nlocal Parallel = require \"actions/Parallel\"\nlocal Serial = require \"actions/Serial\"\nlocal Wait = require \"actions/Wait\"\nlocal While = require \"actions/While\"\nlocal Do = require \"actions/Do\"\nlocal YieldUntil = require \"actions/YieldUntil\"\nlocal shine = require \"lib/shine\"\nlocal SpriteNode = require \"object/SpriteNode\"\nlocal Spawn = require \"actions/Spawn\"\nlocal AudioFade = require \"actions/AudioFade\"\nlocal Repeat = require \"actions/Repeat\"\nlocal BlockPlayer = require \"actions/BlockPlayer\"\n\nlocal BasicNPC = require \"object/BasicNPC\"\nlocal EscapeObstacle = require \"object/EscapeObstacle\"\nlocal EscapeHoverbot = require \"object/EscapeHoverbot\"\nlocal EscapeIndicator = require \"object/EscapeIndicator\"\n\nlocal SpriteNode = require \"object/SpriteNode\"\nlocal EscapePlayer = require \"object/EscapePlayer\"\n\nreturn function(self)\n    return BlockPlayer {\n        Do(function()\n            scene.player:removeSceneHandler(\"update\", EscapePlayer.update)\n            scene.player.dropShadow.hidden = true\n        end),\n\n        Parallel {\n            AudioFade(\"music\", 1, 0, 1),\n            Ease(scene.player, \"x\", function() return scene.player.x + 800 end, 1.5, \"linear\"),\n            Serial {\n                Wait(0.5),\n                Do(function() scene.player.sprite:setAnimation(\"shock\") end)\n            },\n            Serial {\n                Ease(scene.player, \"y\", function() return scene.player.y + 100 end, 1.5, \"quad\"),\n                Parallel {\n                    Ease(scene.player.sprite.transform, \"angle\", math.pi/2, 3, \"linear\"),\n                    Ease(scene.player, \"y\", function() return scene.player.y + 600 end, 5, \"linear\")\n                }\n            }\n        },\n			\n        Wait(3),\n        MessageBox{message=\"YES!!!\", textSpeed=3, closeAction=Wait(2)},\n        Wait(1),\n\n        Do(function()\n            scene.objectLookup.Snively.hidden = false\n            scene.objectLookup.Snively.sprite.sortOrderY = 10000\n            scene.objectLookup.Cheetah.hidden = false\n        end),\n\n        Parallel {\n            Serial {\n                Move(scene.objectLookup.Snively, scene.objectLookup.SnivelyWP, \"walk\"),\n                Animate(scene.objectLookup.Snively.sprite, \"idleright_smile\")\n            },\n            Ease(scene.camPos, \"x\", 760, 0.2, \"linear\")\n        },\n\n        PlayAudio(\"music\", \"wearefucked\", 1, true),\n        MessageBox{message=\"Snively: You've done very well, my pet...\", textSpeed=3, closeAction=Wait(3)},\n        Wait(1),\n        Animate(scene.objectLookup.Snively.sprite, \"idleright_lookleft\"),\n        MessageBox{message=\"Snively: ...{p80}can't have the big round guy finding out\\nabout this, though...\", textSpeed=3, closeAction=Wait(3)},\n        Do(function() scene.objectLookup.Snively.sprite:setAnimation(\"stepback_left\") end),\n        Ease(scene.objectLookup.Snively, \"x\", function() return scene.objectLookup.Snively.x - 25 end, 1, \"linear\"),\n        Animate(scene.objectLookup.Snively.sprite, \"prep_kick\"),\n        Parallel {\n            Animate(scene.objectLookup.Snively.sprite, \"kick\"),\n            Ease(scene.objectLookup.Snively, \"x\", function() return scene.objectLookup.Snively.x + 70 end, 4),\n            Serial {\n                Wait(0.2),\n                PlayAudio(\"sfx\", \"smack\", 1, true),\n                Animate(scene.objectLookup.Cheetah.sprite, \"kicked\"),\n                Parallel {\n                    Ease(scene.objectLookup.Cheetah, \"x\", function() return scene.objectLookup.Cheetah.x + 80 end, 2, \"linear\"),\n                    Ease(scene.objectLookup.Cheetah, \"y\", function() return scene.objectLookup.Cheetah.y - 100 end, 4),\n                },\n                Ease(scene.objectLookup.Cheetah, \"x\", function() return scene.objectLookup.Cheetah.x + 80 end, 2, \"linear\"),\n                Parallel {\n                    Ease(scene.objectLookup.Cheetah, \"x\", function() return scene.objectLookup.Cheetah.x + 80 end, 4, \"linear\"),\n                    Ease(scene.objectLookup.Cheetah, \"y\", function() return scene.objectLookup.Cheetah.y + 600 end, 6),\n                }\n            }\n        },\n        Do(function() scene.objectLookup.Snively.sprite:setAnimation(\"idleright_laugh\") end),\n        Wait(2),\n        Do(function() scene.objectLookup.Snively.sprite:setAnimation(\"idleright_smile\") end),\n        MessageBox{message=\"Snively: Now the Princess and her little hedgehog will be hopelessly trapped{p80}, deep within the inescapable {h robot wasteland}...\", textSpeed=3, closeAction=Wait(5)},\n        TypeText(\n            Transform(50, 300),\n            {255, 255, 255, 255},\n            FontCache.Techno,\n            \"TO BE CONTINUED...\",\n            3\n        ),\n        Wait(2),\n        Do(function()\n            scene.sceneMgr:pushScene {class = \"CreditsSplashScene\"}\n        end)\n    }\nend"
